def is_rectangle_outline(grid, r, c, h, w, outline_color):
    """Check if the region from (r,c) with size h,w is a rectangle outline of the given color"""
    rows = len(grid)
    cols = len(grid[0])

    # Check dimensions
    if r + h > rows or c + w > cols:
        return False
    if h < 3 or w < 3:
        return False

    # Check all corners are outline_color
    corners = [(r, c), (r, c+w-1), (r+h-1, c), (r+h-1, c+w-1)]
    for rr, cc in corners:
        if grid[rr][cc] != outline_color:
            return False

    # Check top and bottom rows
    for j in range(w):
        if grid[r][c+j] != outline_color:
            return False
        if grid[r+h-1][c+j] != outline_color:
                return False

    # Check left and right columns
    for i in range(h):
        if grid[r+i][c] != outline_color:
            return False
        if grid[r+i][c+w-1] != outline_color:
            return False

    # Check interior is NOT all outline_color
    for i in range(1, h-1):
        for j in range(1, w-1):
            if grid[r+i][c+j] == outline_color:
                return False

    return True

